plugins {
    alias(libs.plugins.ivrtop.android.library)
    alias(libs.plugins.ivrtop.android.hilt)
}

/*
 * PJSIP / PJSUA2 native engine.
 *
 * The pjsua2 Java bindings (org.pjsip.pjsua2.*) and libpjsua2.so are GENERATED by
 * scripts/pjsip/build-pjsip-android.sh and placed in:
 *     telephony/sip-engine/pjsua2/java/        (SWIG generated sources)
 *     telephony/sip-engine/pjsua2/jniLibs/<abi>/libpjsua2.so (+ libc++_shared.so)
 * They are NOT committed (licence + size). See docs/SIP_ENGINE_RESEARCH.md and docs/LICENSING.md.
 */
val pjsuaDir = layout.projectDirectory.dir("pjsua2")

android {
    namespace = "com.ivrtop.dialer.telephony.sipengine"
    sourceSets {
        getByName("main") {
            java.srcDir(pjsuaDir.dir("java"))
            jniLibs.srcDir(pjsuaDir.dir("jniLibs"))
        }
    }
    defaultConfig {
        ndk {
            // 32-bit ARM kept for older Android 10 devices still common in the field.
            abiFilters += listOf("arm64-v8a", "armeabi-v7a", "x86_64")
        }
    }
    packaging {
        jniLibs {
            // Required for 16 KB page-size devices: libraries must be stored uncompressed & aligned.
            useLegacyPackaging = false
        }
    }
}

val verifyPjsua2 by tasks.registering {
    val javaDir = pjsuaDir.dir("java/org/pjsip/pjsua2").asFile
    val soFile = pjsuaDir.file("jniLibs/arm64-v8a/libpjsua2.so").asFile
    doLast {
        if (!javaDir.exists() || !soFile.exists()) {
            throw GradleException(
                "PJSUA2 bindings missing. Run scripts/pjsip/build-pjsip-android.sh first " +
                    "(expects ${javaDir.path} and ${soFile.path}).",
            )
        }
    }
}
tasks.named("preBuild") { dependsOn(verifyPjsua2) }

dependencies {
    implementation(project(":telephony:sip-api"))
    implementation(project(":core:common"))
    implementation(project(":core:security"))
    implementation(libs.androidx.core.ktx)
}
